let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'zh',phase='pre',team='all',catalog=null,chosen=null,requestId=0,lastRefresh=0;const cache=new Map();
const $=id=>document.getElementById(id),tx=(z,e)=>lang==='zh'?z:e,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=t=>new Intl.DateTimeFormat(lang==='zh'?'zh-CN':'en-GB',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(Date.parse(t));
function labels(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';$('title').textContent=tx('每场比赛，前后有据。','Before tipoff. After the buzzer.');$('edition').textContent=tx('赛前 · 赛后','PREVIEW · FINAL');$('description').innerHTML=tx('赛前球队、名单与伤情资料<br>赛后比分、技术统计与分节表现','Pregame teams, lineups and availability<br>Final scores, box scores and quarter splits');$('snapshot-note').textContent=tx('这是定时发布的资料快照，不提供实时比分或赔率。开赛后，赛前内容保留为存档。','Published snapshots, without live scores or odds. Pregame information becomes an archive after tipoff.');$('footer-note').textContent=tx('数据来自 ESPN / NBA.com 已收包资料。保留缺失与待核，不输出预测。','Captured ESPN / NBA.com evidence. Missing and unverified values remain explicit. No predictions.');$('filter-label').textContent=tx('球队','Team');$('refresh').textContent=tx('检查更新','Check for updates');for(const l of ['zh','en'])$(l).setAttribute('aria-pressed',String(lang===l));if(catalog){const age=(Date.now()-Date.parse(catalog.publishedAt))/3600000;$('updated').textContent=tx('发布快照：','Published: ')+time(catalog.publishedAt)+' '+tx('北京','Beijing')+(age>6?tx(' · 超过6小时，资料可能已变',' · Over 6 hours old; information may have changed'):'');}}
function draw(){labels();for(const p of ['pre','post']){$(p).innerHTML=tx(p==='pre'?'赛前':'赛后',p==='pre'?'Preview':'Final')+` <span>${catalog.games.filter(g=>g.phase===p).length}</span>`;$(p).setAttribute('aria-pressed',String(phase===p));}
 const codes=[...new Set(catalog.games.flatMap(g=>[g.teams.away.abbr,g.teams.home.abbr]))].sort();$('team').innerHTML=`<option value="all">${tx('全部球队','All teams')}</option>`+codes.map(t=>`<option value="${t}">${t}</option>`).join('');$('team').value=team;
 const games=catalog.games.filter(g=>g.phase===phase&&(team==='all'||Object.values(g.teams).some(t=>t.abbr===team)));
 $('cards').innerHTML=games.map(g=>{const expired=g.phase==='pre'&&Date.now()>=Date.parse(g.startAt);return `<button class="game-card${g.id===chosen?' selected':''}" data-game="${g.id}" aria-pressed="${g.id===chosen}"><span class="card-top">${time(g.startAt)} ${tx('北京','BJ')}<b>${g.phase==='post'?tx('终场','FINAL'):expired?tx('赛前存档','ARCHIVE'):tx('赛前','PREVIEW')}</b></span><span class="matchup"><span>${g.teams.away.abbr}</span><small>@</small><span>${g.teams.home.abbr}</span></span><span class="card-bottom">${g.phase==='post'?`${g.scores?.[g.teams.away.abbr]??'—'} <small>–</small> ${g.scores?.[g.teams.home.abbr]??'—'}`:tx('查看球队与赛前资料','Team and pregame evidence')}<span>↗</span></span></button>`;}).join('')||`<p class="empty">${tx('当前没有符合条件的已发布比赛。','No published games match this filter.')}</p>`;
 if(!games.some(g=>g.id===chosen))chosen=games[0]?.id||null;
 if(chosen)show(chosen);else $('detail').innerHTML='';
}
async function show(id){chosen=id;document.querySelectorAll('[data-game]').forEach(b=>{b.classList.toggle('selected',b.dataset.game===id);b.setAttribute('aria-pressed',String(b.dataset.game===id));});const n=++requestId,g=catalog.games.find(g=>g.id===id);$('detail').innerHTML=`<p class="empty">${tx('正在读取比赛资料…','Loading game evidence…')}</p>`;try{if(!cache.has(g.file)){const r=await fetch('/'+g.file);if(!r.ok)throw Error();cache.set(g.file,await r.json());}if(n!==requestId)return;const expired=g.phase==='pre'&&Date.now()>=Date.parse(g.startAt);$('detail').innerHTML=(expired?`<p class="notice">${tx('计划开赛时间已到：以下仅为发布时的赛前存档，不代表当前名单或比赛状态。','Scheduled tipoff has passed. This is a pregame archive, not the current lineup or game status.')}</p>`:'')+cache.get(g.file)[lang];history.replaceState(null,'','?game='+id+'&lang='+lang);}catch{$('detail').innerHTML=`<p class="notice">${tx('暂时无法读取这场资料，请稍后检查更新。','This game could not be loaded. Please try again later.')}</p>`;}}
async function load(){try{const r=await fetch('/data/index.json',{cache:'no-cache'});if(!r.ok)throw Error();catalog=await r.json();if(catalog.version!=='courtvision-static-v1'||catalog.games.some(g=>!['pre','post'].includes(g.phase)||!/^data\/\d+-[a-f0-9]+\.json$/.test(g.file)))throw Error();const q=new URLSearchParams(location.search).get('game');if(!chosen&&q&&catalog.games.some(g=>g.id===q)){chosen=q;phase=catalog.games.find(g=>g.id===q).phase;}else if(!catalog.games.some(g=>g.phase===phase))phase='post';draw();}catch{$('updated').textContent=tx('快照暂时不可用，请稍后重试。','Snapshot unavailable. Please try again later.');}finally{$('refresh').disabled=false;}}
for(const l of ['zh','en'])$(l).onclick=()=>{lang=l;draw();};for(const p of ['pre','post'])$(p).onclick=()=>{phase=p;chosen=null;draw();};$('team').onchange=e=>{team=e.target.value;chosen=null;draw();};$('cards').onclick=e=>{const b=e.target.closest('[data-game]');if(b)show(b.dataset.game);};$('refresh').onclick=()=>{if(Date.now()-lastRefresh<60000)return;lastRefresh=Date.now();$('refresh').disabled=true;load();};$('detail').onclick=e=>{const b=e.target.closest('[data-quarter-player]');if(b){const group=b.closest('.quarter-group'),tpl=group.closest('.quarter-team').querySelector(`template[data-history="${b.dataset.quarterPlayer}"]`);if(tpl){group.querySelector('.rt-quarter-detail').replaceWith(tpl.content.cloneNode(true));group.querySelectorAll('[data-quarter-player]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}}};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&catalog)draw();});labels();load();
